53	func (s *APIV1Service) setMemoAttachmentsInternal(ctx context.Context, user *store.User, memo *store.Memo, requestAttachments []*v1pb.Attachment) error {
54		currentAttachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{
55			MemoID: &memo.ID,
56		})
57		if err != nil {
58			return status.Errorf(codes.Internal, "failed to list attachments")
59		}
60	
61		normalizedAttachments, err := s.normalizeMemoAttachmentRequest(ctx, user, currentAttachments, requestAttachments)
62		if err != nil {
63			return err
64		}
65	
66		requestedIDs := make(map[int32]bool, len(normalizedAttachments))
67		for _, attachment := range normalizedAttachments {
68			requestedIDs[attachment.ID] = true
69		}
70	
71		// Delete attachments that are not in the request.
72		for _, attachment := range currentAttachments {
73			if !requestedIDs[attachment.ID] {
74				if attachment.CreatorID != user.ID && !isSuperUser(user) {
75					return status.Errorf(codes.PermissionDenied, "cannot remove another user's attachment")
76				}
77				if err = s.Store.DeleteAttachment(ctx, &store.DeleteAttachment{
78					ID:     int32(attachment.ID),
79					MemoID: &memo.ID,
80				}); err != nil {
81					return status.Errorf(codes.Internal, "failed to delete attachment")
82				}
83			}
84		}
85	
86		slices.Reverse(normalizedAttachments)
87		// Update attachments' memo_id in the request.
88		for index, attachment := range normalizedAttachments {
89			updatedTs := time.Now().Unix() + int64(index)
90			if err := s.Store.UpdateAttachment(ctx, &store.UpdateAttachment{
91				ID:        attachment.ID,
92				MemoID:    &memo.ID,
93				UpdatedTs: &updatedTs,
94			}); err != nil {
95				return status.Errorf(codes.Internal, "failed to update attachment: %v", err)
96			}
97		}
98	
99		return nil
100	}
101	
102	func (s *APIV1Service) normalizeMemoAttachmentRequest(
103		ctx context.Context,
104		user *store.User,
105		currentAttachments []*store.Attachment,
106		requestAttachments []*v1pb.Attachment,
107	) ([]*store.Attachment, error) {
108		requestedAttachments := make([]*store.Attachment, 0, len(requestAttachments))
109		for _, requestAttachment := range requestAttachments {
110			attachmentUID, err := ExtractAttachmentUIDFromName(requestAttachment.Name)
111			if err != nil {
112				return nil, status.Errorf(codes.InvalidArgument, "invalid attachment name: %v", err)
113			}
114			attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{UID: &attachmentUID})
115			if err != nil {
116				return nil, status.Errorf(codes.Internal, "failed to get attachment: %v", err)
117			}
118			if attachment == nil {
119				return nil, status.Errorf(codes.NotFound, "attachment not found: %s", attachmentUID)
120			}
121			if attachment.CreatorID != user.ID && !isSuperUser(user) {
122				return nil, status.Errorf(codes.PermissionDenied, "cannot attach another user's attachment")
123			}
124			requestedAttachments = append(requestedAttachments, attachment)
125		}
126	
127		currentGroups := make(map[string][]*store.Attachment)
128		for _, attachment := range currentAttachments {
129			motion := getAttachmentMotionMedia(attachment)
130			if motion == nil || motion.GroupId == "" {
131				continue
132			}
133			currentGroups[motion.GroupId] = append(currentGroups[motion.GroupId], attachment)
134		}
135	
136		requestGroups := make(map[string][]*store.Attachment)
137		requestNamesByGroup := make(map[string]map[string]bool)
138		for _, attachment := range requestedAttachments {
139			motion := getAttachmentMotionMedia(attachment)
140			if motion == nil || motion.GroupId == "" {
141				continue
142			}
143			requestGroups[motion.GroupId] = append(requestGroups[motion.GroupId], attachment)
144			if requestNamesByGroup[motion.GroupId] == nil {
145				requestNamesByGroup[motion.GroupId] = make(map[string]bool)
146			}
147			requestNamesByGroup[motion.GroupId][attachment.UID] = true
148		}
149	
150		normalized := make([]*store.Attachment, 0, len(requestedAttachments))
151		appendedGroups := make(map[string]bool)
152		appendedAttachments := make(map[string]bool)
153		for _, attachment := range requestedAttachments {
154			motion := getAttachmentMotionMedia(attachment)
155			if motion == nil || motion.GroupId == "" {
156				if !appendedAttachments[attachment.UID] {
157					normalized = append(normalized, attachment)
158					appendedAttachments[attachment.UID] = true
159				}
160				continue
161			}
162	
163			groupID := motion.GroupId
164			if appendedGroups[groupID] {
165				continue
166			}
167	
168			currentGroup := currentGroups[groupID]
169			if isMultiMemberMotionGroup(currentGroup) && !allGroupMembersRequested(currentGroup, requestNamesByGroup[groupID]) {
170				appendedGroups[groupID] = true
171				continue
172			}
173	
174			for _, groupAttachment := range requestGroups[groupID] {
175				if appendedAttachments[groupAttachment.UID] {
176					continue
177				}
178				normalized = append(normalized, groupAttachment)
179				appendedAttachments[groupAttachment.UID] = true
180			}
181			appendedGroups[groupID] = true
182		}
183	
184		return normalized, nil
185	}
186	
187	func allGroupMembersRequested(group []*store.Attachment, requestedNames map[string]bool) bool {
188		if len(group) == 0 {
189			return false
190		}
191	
192		for _, attachment := range group {
193			if !requestedNames[attachment.UID] {
194				return false
195			}
196		}
197		return true
198	}
199	
200	func (s *APIV1Service) ListMemoAttachments(ctx context.Context, request *v1pb.ListMemoAttachmentsRequest) (*v1pb.ListMemoAttachmentsResponse, error) {
201		memoUID, err := ExtractMemoUIDFromName(request.Name)
202		if err != nil {
203			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
204		}
205		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
206		if err != nil {
207			return nil, status.Errorf(codes.Internal, "failed to get memo: %v", err)
208		}
209		if memo == nil {
210			return nil, status.Errorf(codes.NotFound, "memo not found")
211		}
212	
213		// Check memo visibility.
214		if memo.Visibility != store.Public {
215			user, err := s.fetchCurrentUser(ctx)
216			if err != nil {
217				return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
218			}
219			if user == nil {
220				return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
221			}
222			if memo.Visibility == store.Private && memo.CreatorID != user.ID && !isSuperUser(user) {
223				return nil, status.Errorf(codes.PermissionDenied, "permission denied")
224			}
225		}
226	
227		attachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{
228			MemoID: &memo.ID,
229		})
230		if err != nil {
231			return nil, status.Errorf(codes.Internal, "failed to list attachments: %v", err)
232		}
233	
234		response := &v1pb.ListMemoAttachmentsResponse{
235			Attachments: []*v1pb.Attachment{},
236		}
237		for _, attachment := range attachments {
238			response.Attachments = append(response.Attachments, convertAttachmentFromStore(attachment))
239		}
240		return response, nil
241	}
